source binding/reference str in _bfs_reaches@63; its value/role follows this source operation, not a universal meaning shared with other scopes: def _bfs_reaches(start: str, graph: dict, sinks: set[str], max_hops: int) -> set[str]:
    if not start:
        return set()
    hit: set[str] = set()
    seen = {start}
    q = deque([(start, 0)])
    while q:
        node, d = q.popleft()
        for nx in graph.get(node, ()):
            if nx in seen:
                continue
            seen.add(nx)
            if nx in sinks:
                hit.add(nx)
            if d + 1 < max_hops:
                q.append((nx, d + 1))
    return hit

