source binding/reference AnalysisNode in _qualified_flow_name@431; its value/role follows this source operation, not a universal meaning shared with other scopes: def _qualified_flow_name(entry: AnalysisNode) -> str:
    package = ""
    if entry.file_path:
        directory = posixpath.dirname(entry.file_path)
        if directory not in (".", "/", ""):
            package = posixpath.basename(directory)
    parts = [
        part
        for part in (package, entry.owner_name if entry.label == "Method" else "", entry.name)
        if part
    ]
    return ".".join(parts) + "-flow"

