callable _find_entry_points in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _find_entry_points(graph: FlowGraph, exclude_tests: bool) -> list[str]:
    entry_points: list[str] = []
    for node in graph.callable_ids():
        symbol = graph.symbols[node]
        if exclude_tests and is_test_file(symbol.file_path):
            continue
        if not graph.incoming_of(node, "CALLS"):
            entry_points.append(node)
    return entry_points

callable _find_orchestrators in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _find_orchestrators(graph: FlowGraph, existing: set[str], exclude_tests: bool) -> list[str]:
    orchestrators: list[str] = []
    all_relationships = ("CALLS", "SPAWNS", "DELEGATES_TO")
    for node in graph.callable_ids():
        if node in existing:
            continue
        symbol = graph.symbols[node]
        if exclude_tests and is_test_file(symbol.file_path):
            continue
        production = graph.production_callers(node, all_relationships)
        if production == 0 or production > ORCHESTRATOR_MAX_CALLERS:
            continue

callable _qualified_flow_name in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _qualified_flow_name(entry: AnalysisNode) -> str:
    package = ""
    if entry.file_path:
        directory = posixpath.dirname(entry.file_path)
        if directory not in (".", "/", ""):
            package = posixpath.basename(directory)
    parts = [
        part
        for part in (package, entry.owner_name if entry.label == "Method" else "", entry.name)
        if part
    ]
    return ".".join(parts) + "-flow"

callable _spawn_sibling_counts in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _spawn_sibling_counts(graph: FlowGraph) -> dict[str, int]:
    fanout: dict[str, int] = {}
    for source, edges in graph.outgoing.items():
        fanout[source] = sum(1 for _, rel, _ in edges if rel == "SPAWNS")
    siblings: dict[str, int] = {}
    for target, edges in graph.incoming.items():
        for source, rel, _ in edges:
            if rel == "SPAWNS":
                siblings[target] = max(siblings.get(target, 0), fanout.get(source, 0))
    return siblings

