callable clean_type_name in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def clean_type_name(text: str) -> str:
    text = text.strip().removeprefix(":").strip()
    for opener in "<[":
        index = text.find(opener)
        if index > 0:
            text = text[:index]
    text = text.removesuffix("?").removeprefix("*").removeprefix("&")
    scope = text.rfind("::")
    if scope >= 0:
        text = text[scope + 2 :]
    dot = text.rfind(".")
    if dot >= 0:
        text = text[dot + 1 :]
    backslash = text.rfind("\\")
    if backslash >= 0:
        text = text[backslash + 1 :]
    return text.strip()

