    descriptor: LanguageDescriptor, def_node: Node, source: bytes
) -> str:
    annotations = extract_annotations(def_node, source)
    if descriptor.annotation_supplement is None:
        return annotations
    existing = annotations.split(",") if annotations else []
    for name in descriptor.annotation_supplement(def_node, source):
