    blocks: list[str] = []
    for match in re.finditer(r"\bdependencies\s*\{", content):
        depth = 0
        for index in range(match.end() - 1, len(content)):
            if content[index] == "{":
                depth += 1
            elif content[index] == "}":
                depth -= 1
                if depth == 0:
                    blocks.append(content[match.end() : index])
                    break
    return blocks

