    reader: ManifestReader, relative: str, config: ProjectConfig, seen: set[str]
) -> None:
    normalized = posixpath.normpath(relative)
    if normalized in seen or len(seen) >= _MAX_REQUIREMENT_INCLUDES:
        return
    seen.add(normalized)
    text = reader.read_text(normalized)
    if text is None:
        return
    lines = text.split("\n")
    index = 0
    while index < len(lines):
        line = lines[index]
        index += 1
        while line.rstrip(" \t").endswith("\\") and index < len(lines)

