source binding/reference bool in _dir_excluded@221; its value/role follows this source operation, not a universal meaning shared with other scopes: def _dir_excluded(rel: str, scope: frozenset[str] | None) -> bool:
    """Whether ``ls`` should hide directory *rel* under the registered inventory *scope*."""
    if any(part.lower() in _scan_scope._ALWAYS_EXCLUDED_DIRS for part in rel.split("/")):
        return True
    # .vvaharness/skills post-dates s1's walk; without this exemption every scan loads zero skills
    if _scan_scope._always_allowed(rel + "/"):
        return False
    return bool(rel) and scope is not None and rel not in _in_scope_dirs(scope)

