source binding/reference BackendProtocol in _session_backend@290; its value/role follows this source operation, not a universal meaning shared with other scopes: def _session_backend(
    options: OneShotOptions | StreamingOptions,
) -> BackendProtocol | None:
    """Use a real, repo-confined filesystem; read-only sessions still need native reads."""
    # Always disk-backed: native read_file/grep/glob are the only read path; StateBackend is empty.
    _filesystem_permissions(options)
    # Opt-in per site, keyed off the SAME permitted_tool_calls as the gate, so the two cannot drift
    if getattr(options, "permitted_tool_calls", None) is not None:
        return _scoped_backend(options)

