source binding/reference Any in _reforce@69; its value/role follows this source operation, not a universal meaning shared with other scopes: def _reforce(bound: Runnable[Any, Any], forced: dict[str, Any]) -> Runnable[Any, Any]:
    """Re-apply *forced* to *bound*, carrying over any disable_parallel_tool_use langchain set."""
    held = getattr(bound, "kwargs", None)
    if not isinstance(held, dict):
        return bound
    if held.get("tool_choice", {}).get("type") in _FORCED_TYPES:
        return bound
    existing = held.get("tool_choice") or {}
    if "disable_parallel_tool_use" in existing:
        forced["disable_parallel_tool_use"] = existing["disable_parallel_tool_use"]
    COUNTERS

