source binding/reference BaseTool in _permitted_for_spec@106; its value/role follows this source operation, not a universal meaning shared with other scopes: def _permitted_for_spec(
    tool_names: Sequence[str], tools: Sequence[BaseTool]
) -> frozenset[str]:
    """Executor-permitted names for one sub-agent: its NATIVE tool names, not its logical ones."""
    native = {LOGICAL_TO_NATIVE.get(t, t) for t in tool_names}
    if native & {LOGICAL_TO_NATIVE[r] for r in READ_TOOLS}:
        native |= NATIVE_IMPLIED_READS
    return frozenset(native | {t.name for t in tools})

