source binding/reference str in prefix_cache_class@37; its value/role follows this source operation, not a universal meaning shared with other scopes: def prefix_cache_class(via: str, *, model_id: str = "",
                       provider: str | None = None) -> str:
    """The prompt-prefix caching mechanism a route's requests can use."""
    if via == "sdk":
        return PREFIX_CACHE_BREAKPOINT
    if via == "openai":
        return PREFIX_CACHE_IMPLICIT
    if via == "deepagents":
        if routes_to_anthropic(model_id, provider):
            return PREFIX_CACHE_BREAKPOINT
        return PREFIX_CACHE_IMPLICIT
    return PREFIX_CACHE_NONE

