source binding/reference str in _extract_envelope_error@219; its value/role follows this source operation, not a universal meaning shared with other scopes: def _extract_envelope_error(stdout: str | None) -> str | None:
    """If stdout is a claude --output-format json envelope carrying an error, return a one-line summary."""
    if not stdout:
        return None
    s = stdout.strip()
    # Anchor on whichever bracket comes first so the list envelope isn't truncated at an inner '{'.
    candidates = [p for p in (s.find("{"), s.find("[")) if p >= 0]
    if not candidates:
        return None
    try:
        env = json.loads(s[min(candidates):])
    except Exception:
        return None

