    """Serialized ``structured_output`` off a CLI result event, when it carries one."""
    payload = (event or {}).get("structured_output")
    if not isinstance(payload, (dict, list)):
        return None
    try:
        return json.dumps(payload)
    except (TypeError, ValueError):      # non-serializable payload — fall back to `result`
        return None

