callable _tool_call_from_item in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _tool_call_from_item(item: Any) -> _ToolCall:
    # Allowlist by construction: only call_id/name/arguments/id are ever read off *item*, so an
    # OUTPUT-only field such as `status` never reaches the stored tool call or its replay.
    return _ToolCall(
        _get(item, "call_id"), _get(item, "name"), _get(item, "arguments"), _get(item, "id"),
    )

callable _tool_kwargs in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _tool_kwargs(base_kw: dict) -> dict:
    kwargs: dict = {}
    tools = to_responses_tools(base_kw.get("tools"))
    if tools:
        kwargs["tools"] = tools
    tool_choice = base_kw.get("tool_choice")
    if tool_choice is not None:
        kwargs["tool_choice"] = to_responses_tool_choice(tool_choice)
    return kwargs

source binding/reference dict in to_chat_messages@236; its value/role follows this source operation, not a universal meaning shared with other scopes: def to_chat_messages(messages: list[dict]) -> list[dict]:
    """Copy a transcript with the Responses-only replay keys stripped, for the Chat wire."""
    out = []
    for entry in messages:
        copy = {k: v for k, v in entry.items() if k != REASONING_ITEMS_KEY}
        tool_calls = copy.get("tool_calls")
        if tool_calls:
            copy["tool_calls"] = [
                {k: v for k, v in tc.items() if k != ITEM_ID_KEY} for tc in tool_calls
            ]
        out.append(copy)
    return out

