    """Render a prompt as one string, joining the text blocks of a content-block list."""
    if isinstance(user_prompt, str):
        return user_prompt
    return "\n\n".join(
        str(b.get("text", "")) for b in user_prompt
        if isinstance(b, dict) and b.get("type") == "text"
    )

