source binding/reference Path in _dotenv_path_is_trusted@29; its value/role follows this source operation, not a universal meaning shared with other scopes: def _dotenv_path_is_trusted(path: Path) -> bool:
    """Reject unsafe POSIX ownership/modes; exact-location checks protect other OSes."""
    try:
        entries = (path.parent.stat(), path.stat())
    except OSError:
        return False
    get_euid = getattr(os, "geteuid", None)
    if get_euid is None:
        return True
    effective_uid = get_euid()
    for entry in entries:
        if entry.st_uid != effective_uid:
            return False
        if entry.st_mode & (stat.S_IWGRP | stat.S_IWOTH):
            return False
    ret

