source binding/reference Path in _symlinked_ancestor@32; its value/role follows this source operation, not a universal meaning shared with other scopes: def _symlinked_ancestor(path: Path, anchor: Path) -> Path | None:
    """The first symlink at *path* itself or an existing dir between it and *anchor*, or None."""
    node = path
    while node != anchor and node != node.parent:
        try:
            lst = node.lstat()
        except OSError:
            lst = None  # nothing at this level yet — not a symlink, keep walking up
        if lst is not None and stat.S_ISLNK(lst.st_mode):
            return node
        node = node.parent
    return None

