source binding/reference BaseTool in _community_of_tool@226; its value/role follows this source operation, not a universal meaning shared with other scopes: def _community_of_tool(gtx: GraphToolContext) -> BaseTool:
    """Builds ``GraphCommunityOf``, a pure scan of ``ctx.modules`` that touches no graph."""

    @tool
    @_counted
    def GraphCommunityOf(file: str) -> str | None:  # noqa: N802
        """Which module/community *file* belongs to, or None if unmapped. `file` is the exact repo-relative path."""  # noqa: E501
        for name, files in _community_files(gtx.ctx).items():
            if file in files:
                return name
        return None

    return GraphCommunityOf

