    """Keep only the name/version/dependency keys of a package.json-shaped manifest."""
    try:
        data = json.loads(raw)
    except Exception:
        log.debug("manifest structural truncation: unparseable JSON", exc_info=True)
        return None
    if not isinstance(data, dict):
        return None
    keep = {k: v for k, v in data.items() if k in _PACKAGE_JSON_KEYS}
    return _cap_text(json.dumps(keep, indent=2, sort_keys=True), cap) if keep else None

