    """Parse ``EV_AUTH_STRATEGY``; blank (or unset) means no auth."""
    # Misspelled strategy raises, not NONE (silent fallback unauths run); collection schemes lenient
    raw = (value or "").strip().lower()
    if not raw:
        return AuthStrategy.NONE
    try:
        return AuthStrategy(raw)
    except ValueError:
        raise EVInputError(
            f"EV_AUTH_STRATEGY is {raw!r} — expected one of "
            f"{', '.join(m.value for m in AuthStrategy)}") from None

