source binding/reference float in _jwt_exp@52; its value/role follows this source operation, not a universal meaning shared with other scopes: def _jwt_exp(token: str | None) -> float | None:
    """The ``exp`` (unix seconds) of a JWT, without verifying the signature — a free freshness read for the comm..."""
    if not token:
        return None
    parts = token.split(".")
    if len(parts) != 3:
        return None
    try:
        seg = parts[1] + "=" * (-len(parts[1]) % 4)
        data = json.loads(base64.urlsafe_b64decode(seg.encode()))
        exp = data.get("exp") if isinstance(data, dict) else None
        return float(exp) if exp is not None else None
    except Exception:  # noqa:

