source binding/reference str in _dynamic_var@40; its value/role follows this source operation, not a universal meaning shared with other scopes: def _dynamic_var(name: str) -> str | None:
    """Resolve a Postman dynamic variable (``{{$guid}}`` etc.) to a concrete value, or None if unrecognized."""
    n = name.lstrip("$").lower()
    if n in ("guid", "randomuuid"):
        return str(uuid.uuid4())
    if n == "timestamp":
        return str(int(time.time()))
    if n == "isotimestamp":
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    if n == "randomint":
        return str(random.randint(0, 1000))
    return None

