        """Block until a target slot AND an endpoint slot are free, hold both for the wrapped send, then release."""
        ep = self._endpoint_sem(method, path)
        if self._target is not None:
            self._target.acquire()
        if ep is not None:
            ep.acquire()
        try:
            yield
        finally:
            if ep is not None:
                ep.release()
            if self._target is not None:
                self._target.release()

