    """Place ``value`` relative to the endpoint's legitimate value."""
    # {{BASE}} prepends the real value (`127.0.0.1; id`); without it the payload replaces it whole
    if value is not None and "{{BASE}}" in value:
        return value.replace("{{BASE}}", str(base_val or ""))
    return value

