source binding/reference str in mask_cookie_values@177; its value/role follows this source operation, not a universal meaning shared with other scopes: def mask_cookie_values(value: str) -> str:
    """Mask the credential in a ``set-cookie`` while keeping its name and attributes."""
    # Session ids are opaque, so mask by VALUE: key-name masking would take HttpOnly/Secure evidence
    parts = []
    for segment in str(value).split(";"):
        name, sep, val = segment.partition("=")
        if sep and name.strip().lower() not in _COOKIE_FLAGS and val.strip():
            parts.append(f"{name}={_REDACTED}")
        else:
            parts.append(segment)
    return ";".join(parts)

