callable _config_sha256 in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _config_sha256(cfg_path: Path) -> str | None:
    if not cfg_path.exists():
        return None
    try:
        return hashlib.sha256(cfg_path.read_bytes()).hexdigest()
    except OSError as e:
        console.write(f"  [manifest] could not hash config {cfg_path}: {e}")
        return None

callable _git_sha in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _git_sha(args: list[str]) -> str | None:
    repo = None
    for i, a in enumerate(args):
        if a == "--repo" and i + 1 < len(args):
            repo = args[i + 1]
        elif a.startswith("--repo="):
            repo = a.split("=", 1)[1]
    if not repo:
        return None
    # --repo is data: validated here pre-orchestrator, cwd= not -C; hardening, not a live exploit
    try:
        repo_dir = Path(repo).resolve()
        if not repo_dir.is_dir():
            return None
    except (OSError, ValueError):
        return None
    try:
        out = subproc

callable _input_fingerprint in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _input_fingerprint(value, config_dir: Path) -> dict | None:
    if value is None or not str(value).strip():
        return None
    configured_path = Path(str(value))
    resolved_path = configured_path if configured_path.is_absolute() else config_dir / configured_path
    return {
        "path": str(configured_path),
        "sha256": _config_sha256(resolved_path),
    }

