source binding/reference int in _coerce_int@36; its value/role follows this source operation, not a universal meaning shared with other scopes: def _coerce_int(v, default: int = 0) -> int:
    if isinstance(v, bool):                # bool ⊂ int in Python; reject
        return default
    if isinstance(v, int):
        return v
    if isinstance(v, float):
        # int(nan) raises ValueError and int(inf) raises OverflowError.
        if v != v or v in (float("inf"), float("-inf")):  # noqa: PLR0124 -- idiomatic NaN check
            return default
        return int(v)
    try:
        return int(str(v).strip())
    except (TypeError, ValueError):
        return default

