source binding/reference ContextPackage in graph_qnodes_by_file@85; its value/role follows this source operation, not a universal meaning shared with other scopes: def graph_qnodes_by_file(ctx: ContextPackage) -> dict[str, list[str]]:
    """``file -> ordered unique list of every qnode ctx.call_graph places in it``."""
    out: dict[str, list[str]] = defaultdict(list)
    seen: dict[str, set[str]] = defaultdict(set)
    for qn in (getattr(ctx, "call_graph", None) or {}):
        f = _q_file(qn)
        if f and qn not in seen[f]:
            out[f].append(qn)
            seen[f].add(qn)
    return dict(out)

