    """Index seed taint paths by every file they touch."""
    out: dict[str, list[list[str]]] = defaultdict(list)
    for path in seed_taint_paths or ():
        touched: set[str] = set()
        for hop in path:
            f, _ln = parse_hop(hop)
            if f:
                touched.add(f)
        for f in touched:
            out[f].append(path)
    return out

