callable _norm_list in module; its value/role follows this source operation, not a universal meaning shared with other scopes: def _norm_list(v, *, lower: bool = False) -> list[str]:
    if not v:
        return []
    if isinstance(v, str):
        v = [v]
    out: list[str] = []
    for x in v:
        if not isinstance(x, str):
            continue
        x = x.strip().strip("/\\")
        if not x:
            continue
        out.append(x.lower() if lower else x)
    seen: set[str] = set()
    uniq = []
    for x in out:
        if x not in seen:
            seen.add(x)
            uniq.append(x)
    return uniq

