source binding/reference re in _mask_pan@454; its value/role follows this source operation, not a universal meaning shared with other scopes: def _mask_pan(m: re.Match) -> str:
    s = m.group(0)
    digits = re.sub(r"\D", "", s)
    if len(digits) < 13:
        return s
    # Luhn-or-keyword gate (length-only mangles timestamps/ids): CWE-201 egress; BIN+layout survive
    window = m.string[max(0, m.start() - 48): m.start()]
    if not (_luhn(digits) or _CARD_CTX.search(window)):
        return s
    kept = 0
    out = []
    for c in s:
        if c.isdigit():
            out.append(c if kept < 4 else "X")
            kept += 1
        else:
            out.append(c)
    return "".join(out)

