source binding/reference Finding in is_secret_class@53; its value/role follows this source operation, not a universal meaning shared with other scopes: def is_secret_class(f: Finding) -> bool:
    """True when *f* is point-of-occurrence, so a test-path match must not exclude it."""
    if f.vuln_class == VulnClass.INFO_LEAK:
        return True
    if f.cwe and (f.cwe in HARDCODED_CWES or f.cwe in CONTROL_ABSENCE_CWES):
        return True
    haystack = " ".join(s for s in (f.title, f.description, f.code_snippet) if s)
    return bool(SECRET_TEXT_RX.search(haystack))

