source binding/reference dict in _taint_code_flow@160; its value/role follows this source operation, not a universal meaning shared with other scopes: def _taint_code_flow(source_ref: str, sink_ref: str) -> dict | None:
    """The source-to-sink taint path as a SARIF codeFlow, or None when neither ref exists."""
    steps = [_ref_related_location(role, ref)
             for role, ref in (("source", source_ref), ("sink", sink_ref)) if ref]
    if not steps:
        return None
    return {"threadFlows": [{"locations": [{"location": s, "importance": "essential"}
                                          for s in steps]}]}

source binding/reference str in _taint_code_flow@160; its value/role follows this source operation, not a universal meaning shared with other scopes: def _taint_code_flow(source_ref: str, sink_ref: str) -> dict | None:
    """The source-to-sink taint path as a SARIF codeFlow, or None when neither ref exists."""
    steps = [_ref_related_location(role, ref)
             for role, ref in (("source", source_ref), ("sink", sink_ref)) if ref]
    if not steps:
        return None
    return {"threadFlows": [{"locations": [{"location": s, "importance": "essential"}
                                          for s in steps]}]}

