source binding/reference bool in result_identifies@46; its value/role follows this source operation, not a universal meaning shared with other scopes: def result_identifies(result, case_id: str) -> bool:
    """Whether *result* is the SARIF row for *case_id*, own fingerprint or folded alias."""
    if not case_id:
        return False
    prints = result.get("partialFingerprints") or {}
    if str(prints.get(FINGERPRINT_KEY, "")) == case_id:
        return True
    aliases = (result.get("properties") or {}).get(ALIAS_KEY) or []
    return case_id in aliases

source binding/reference str in result_identifies@46; its value/role follows this source operation, not a universal meaning shared with other scopes: def result_identifies(result, case_id: str) -> bool:
    """Whether *result* is the SARIF row for *case_id*, own fingerprint or folded alias."""
    if not case_id:
        return False
    prints = result.get("partialFingerprints") or {}
    if str(prints.get(FINGERPRINT_KEY, "")) == case_id:
        return True
    aliases = (result.get("properties") or {}).get(ALIAS_KEY) or []
    return case_id in aliases

