                       extra_files: list[str] | None = None) -> str | None:
    """Synthesize a git-style unified diff for a **non-git** target."""
    # extra_files paths have no snapshot baseline, so they render as newly added; never raises
    repo = Path(repo)
    before = before or {}
    # extra_files refs are LLM-controlled: an abs/../symlink escape must NOT enter the diff (CWE-22)
    paths: list[str] = []
    safe: dict[str, Path] = {}
    for ref in list(before.keys()

