    explicit_context = _PEM_SHORT_CONTEXT_RE.search(body) is not None
    if _PEM_HEADER_RE.match(body.strip()):
        return True
    return any(
        payload.startswith(("MII", "MHc", "MIG"))
        or len(payload) >= 24
