source binding/reference str in _read_key@37; its value/role follows this source operation, not a universal meaning shared with other scopes: def _read_key() -> str:
    """Read one keypress; RAISES on a non-TTY stream, which is how the loop picks the numbered prompt."""
    if sys.platform == "win32":  # pragma: no cover - platform-specific
        try:
            import msvcrt
        except ImportError as e:
            raise RuntimeError("no raw keyboard input") from e
        ch = msvcrt.getwch()
        if ch in ("\x00", "\xe0"):           # arrow prefix on Windows
            ch2 = msvcrt.getwch()
            return {"H": UP, "P": DOWN}.get(ch2, OTHER)
        return decode_key(ch)

