source binding/reference Path in workflow_snapshot_paths@34; its value/role follows this source operation, not a universal meaning shared with other scopes: def workflow_snapshot_paths(repo: Path) -> list[str]:
    """Return existing workflow files that must be snapshotted before S10."""
    root = Path(repo) / _WORKFLOW_PREFIX
    if not root.is_dir():
        return []
    try:
        return sorted(
            p.relative_to(repo).as_posix()
            for pattern in ("*.yml", "*.yaml")
            for p in root.glob(pattern)
            if p.is_file()
        )
    except OSError:
        return []

