source binding/reference list in inspect_diff@28; its value/role follows this source operation, not a universal meaning shared with other scopes: def inspect_diff(diff_text: str | None) -> list[str]:
    """Extract the changed-file set (repo-relative paths) from a unified diff."""
    if not diff_text:
        return []
    out: list[str] = []
    seen: set[str] = set()

    def _add(p: str) -> None:
        p = (p or "").strip()
        if not p or p == "/dev/null":
            return
        if p not in seen:
            seen.add(p)
            out.append(p)

    for line in diff_text.splitlines():
        m = _DIFF_GIT_RE.match(line)
        if m:
            _add(m.group(2) or m.group(1)

