    """The CVSS cell, matching the report's three renderings (scored / vector-only / none)."""
    if finding.cvss_score is not None:
        return (f"**{finding.cvss_score:.1f}** ({finding.cvss_rating}) — "
                f"{_vector_span(finding.cvss_vector)}")
    if finding.cvss_vector:
        return _vector_span(finding.cvss_vector)
    return "_not computed_"

