source binding/reference FindingCase in _skipped_reason@117; its value/role follows this source operation, not a universal meaning shared with other scopes: def _skipped_reason(case: FindingCase) -> str:
    """Explain a non-success bucket, distinguishing a failed validation from an untried fix."""
    if _disposition_of(case) is Disposition.FALSE_POSITIVE:
        return "finding rejected as a false positive"
    if case.state is CaseState.FAILED:
        return "fix applied but failed validation; needs rework"
    if case.state is CaseState.OPEN and case.attempts:
        return "fix applied; validation inconclusive, pending re-validation"
    return "remediation not applied; needs review"

