    """Spec §7.2 impact sub-score, whose exponent differs from the §7.3 modified form."""
    if not scope_changed:
        return IMPACT_SCOPE_UNCHANGED_COEFF * iss
    return (IMPACT_SCOPE_CHANGED_COEFF * (iss - IMPACT_OFFSET)
            - IMPACT_PENALTY_COEFF * (iss - IMPACT_PENALTY_OFFSET) ** BASE_IMPACT_EXPONENT)

