    """Severity label per spec §5; NOT sentinel-safe, so callers guard with ``>= 0`` first."""
    if s is None:
        return "Unknown"
    if s == 0.0:
        return "None"
    for upper, label in SEVERITY_BANDS:
        if s < upper:
            return label
    return "Critical"

