    options = dict(spec)
    name = options.pop("name")
    target = BUILTIN_PLUGINS.get(name)
    if target is None:
        raise ValueError(f"unknown sdk plugin {name!r}; known: {sorted(BUILTIN_PLUGINS)}")
    factory = _resolve(target)
    for key in ("configs", "rulesets"):
        if key in options:
            options[key] = tuple(options[key] or ())
    return factory(**options)

