source binding/reference dict in _plugin_specs@35; its value/role follows this source operation, not a universal meaning shared with other scopes: def _plugin_specs(cfg: object) -> tuple[dict, ...]:
    """The profile's ``sdk.plugins`` entries, each a mapping with at least a ``name``."""
    raw = knob(cfg, "sdk.plugins", []) or []
    if not isinstance(raw, (list, tuple)):
        raise TypeError("sdk.plugins must be a list of mappings")
    specs = []
    for entry in raw:
        if not isinstance(entry, dict) or not entry.get("name"):
            raise TypeError(f"each sdk.plugins entry needs a name: {entry!r}")
        specs.append(dict(entry))
    return tuple(specs)

