    """Conforming, name-unique plugins in deterministic order, or a raised ValueError."""
    if len(plugins) > MAX_PLUGINS:
        raise ValueError(f"at most {MAX_PLUGINS} plugins")
    seen: set[str] = set()
    checked: list[VvahPlugin] = []
    for plugin in plugins:
        if not isinstance(plugin, VvahPlugin):
            raise TypeError(f"not a VvahPlugin: {type(plugin).__name__}")
        name = plugin.info.name
        if name in seen:
            raise ValueError

