source binding/reference str in _langsmith_tracing_gate@313; its value/role follows this source operation, not a universal meaning shared with other scopes: def _langsmith_tracing_gate() -> str | None:
    """The env var that switches LangChain/LangSmith tracing ON, or None."""
    # Replicated, not called: langsmith lru_caches its env reads and would be a doctor-load dep
    for group in _TRACING_GATE_ENVS:
        for name in group:
            v = os.environ.get(name)
            if v is not None and v.strip() != "":
                # First non-empty value in the group wins; only exact "true" enables tracing.
                return name if v == "true" else None
    return None

source binding/reference bool in _looks_like_jwt@64; its value/role follows this source operation, not a universal meaning shared with other scopes: def _looks_like_jwt(v: str | None) -> bool:
    """Whether *value* has a JWT prefix shape ('eyJ...') rather than an 'sk-ant-' API key."""
    if not v:
        return False
    if v.startswith("eyJ"):
        return True
    # Some gateways issue opaque JWT-like session tokens that don't begin with eyJ.
    parts = v.split(".")
    if len(parts) == 3 and v.startswith("ey"):
        return all(bool(p) for p in parts)
    return False

