source binding/reference HarnessConfig in validate_model_spec@42; its value/role follows this source operation, not a universal meaning shared with other scopes: def validate_model_spec(cfg: HarnessConfig) -> object | None:
    """Return ``cfg.models.validate.orchestrator``, or None when any level is undefined."""
    models = getattr(cfg, "models", None)
    if models is None:
        return None
    validate = getattr(models, "validate", None)
    if validate is None:
        return None
    return getattr(validate, "orchestrator", None)

