source binding/reference dict in _resolve_raw@44; its value/role follows this source operation, not a universal meaning shared with other scopes: def _resolve_raw() -> dict[str, object]:
    """Return the raw hints mapping from ``inputs/``; empty when absent or malformed."""
    path = _hints_path()
    if not path.exists():
        return {}  # optional operator input — run without per-CWE bypass hints
    raw = _parse_hints(path)
    if raw is None:
        print(
            f"validate: ignoring malformed hints file {path}; "
            f"proceeding without per-CWE bypass hints"
        )
        return {}
    return raw

