source binding/reference ValidatedFinding in _best_md_match@337; its value/role follows this source operation, not a universal meaning shared with other scopes: def _best_md_match(title: str, pairs: list[ValidatedFinding]) -> ValidatedFinding | None:
    """Match an MD heading title to a pair, failing closed to None on ambiguity (CWE-345)."""
    norm = title.strip().lower()
    if not norm:
        return None
    exact = [pair for pair in pairs if _ftitle(pair) == norm]
    if exact:
        return _only(exact)
    return _only([
        pair for pair in pairs
        if (pair_title := _ftitle(pair)) and (pair_title in norm or norm in pair_title)
    ])

