source binding/reference RawCriterion in _consensus_error@140; its value/role follows this source operation, not a universal meaning shared with other scopes: def _consensus_error(criteria: list[RawCriterion]) -> ScoreResult | None:
    """Fail closed when the host panel could not reach consensus on any gate."""
    flagged = sorted(
        criterion.name
        for criterion in criteria
        if criterion.confidence == SynthesisConfidence.FLAGGED.value
    )
    if not flagged:
        return None
    return _inconclusive(
        f"Insufficient persona consensus for gate(s): {', '.join(flagged)}."
    )

