source binding/reference Config in _load_system_prompt@397; its value/role follows this source operation, not a universal meaning shared with other scopes: def _load_system_prompt(config: Config, path_cfg: object) -> str | None:
    """Read the system prompt file if present, else return None."""
    prompt_file = getattr(path_cfg, "system_prompt_file", None)
    if not prompt_file:
        return None
    path = config.paths.prompts_dir / prompt_file
    if not path.exists():
        return None
    return (
        f"{path.read_text().rstrip()}\n\n"
        f"{_synthesis_section(config)}\n\n"
        f"{_rules_section(config)}\n"
    )

