    """Pin an explicit absolute binary or discover one without searching cwd."""
    configured = Path(binary)
    if configured.is_absolute():
        if configured.is_file():
            return str(configured.resolve())
        raise HarnessCLINotFoundError(f"Claude binary does not exist: {binary}")
