source binding/reference Path in _read_bounded@70; its value/role follows this source operation, not a universal meaning shared with other scopes: def _read_bounded(path: Path, max_bytes: int) -> _ReadResult:
    try:
        with path.open("rb") as handle:
            size = os.fstat(handle.fileno()).st_size
            raw_bytes = handle.read(max_bytes)
    except OSError:
        return _ReadResult(unreadable=True)
    observed_size = max(size, len(raw_bytes))
    return _ReadResult(
        data=raw_bytes,
        too_large=observed_size > _MAX_FILE_BYTES,
        binary=NUL_BYTE in raw_bytes,
        has_more=observed_size > max_bytes,
    )

